def sol(parents, pairs):
    n = len(parents)
    depth = [0] * n
    first = [0] + parents[1:]
    for v in range(1, n):
        depth[v] = depth[parents[v]] + 1
    jumps = [first]
    for _ in range(1, n.bit_length()):
        prev = jumps[-1]
        jumps.append([prev[p] for p in prev])
    answer = []
    for a, b in pairs:
        if depth[a] < depth[b]:
            a, b = b, a
        diff = depth[a] - depth[b]
        for k in range(len(jumps)):
            if diff >> k & 1:
                a = jumps[k][a]
        if a != b:
            for row in reversed(jumps):
                if row[a] != row[b]:
                    a, b = row[a], row[b]
            a = first[a]
        answer.append(a)
    return answer

