def sol(n, clauses):
    implications = []
    for a, b in clauses:
        x = 2 * (abs(a) - 1) + (a < 0)
        y = 2 * (abs(b) - 1) + (b < 0)
        implications.extend([[x ^ 1, y], [y ^ 1, x]])
