def sol(values, operations):
    n=len(values)
    top=[0]*(4*n)
    second=[-2**63]*(4*n)
    count=[0]*(4*n)
    total=[0]*(4*n)
    def pull(v):
        a,b=2*v,2*v+1
        total[v]=total[a]+total[b]
        if top[a]==top[b]:
            top[v],second[v],count[v]=top[a],max(second[a],second[b]),count[a]+count[b]
        else:
            if top[a]<top[b]:
                a,b=b,a
            top[v],second[v],count[v]=top[a],max(second[a],top[b]),count[a]
    def build(v,l,r):
        if l+1==r:
            top[v]=total[v]=values[l]
            count[v]=1
            return
        m=(l+r)//2
        build(2*v,l,m)
        build(2*v+1,m,r)
        pull(v)
    def lower(v,x):
        if top[v]>x:
            total[v]-=(top[v]-x)*count[v]
            top[v]=x
    def act(v,l,r,a,b,x,update):
        if r<=a or b<=l:
            return 0
        if update and top[v]<=x:
            return 0
        if a<=l and r<=b:
            if not update:
                return total[v]
            if second[v]<x:
                lower(v,x)
                return 0
        lower(2*v,top[v])
        lower(2*v+1,top[v])
        m=(l+r)//2
        result=act(2*v,l,m,a,b,x,update)+act(2*v+1,m,r,a,b,x,update)
        pull(v)
        return result
    build(1,0,n)
    result=[]
    for mode,l,r,x in operations:
        value=act(1,0,n,l,r+1,x,mode==0)
        if mode==1:
            result.append(value)
    return result

