    def root(u):
        while parent[u]>=0:
            u=parent[u]
        return u
    def visit(k):
        previous=len(history)
        for a,b in intervals[k]:
            a,b=root(a),root(b)
            if a==b:
                continue
            if parent[a]>parent[b]:
                a,b=b,a
            history.append((a,b,parent[a],parent[b]))
            parent[a]+=parent[b]
            parent[b]=a
        if k<size:
            visit(2*k)
            visit(2*k+1)
        elif k-size<len(operations):
            mode,u,v=operations[k-size]
            if mode==2:
                result.append(int(root(u)==root(v)))
        while len(history)>previous:
            a,b,pa,pb=history.pop()
            parent[a],parent[b]=pa,pb
    result=[]
    visit(1)
    return result

def sol(n, edges, pairs):
    m=len(edges)
    low=[-1]*len(pairs)
    high=[m+1]*len(pairs)
    while True:
        groups={}
        for i in range(len(pairs)):
            if high[i]-low[i]>1:
                mid=(low[i]+high[i])//2
                groups.setdefault(mid,[]).append(i)
        if not groups:
            break
        parent=[-1]*n
        def root(v):
            while parent[v]>=0:
                if parent[parent[v]]>=0:
                    parent[v]=parent[parent[v]]
                v=parent[v]
            return v
        for step in range(m+1):
            if step:
                a,b=(root(v) for v in edges[step-1])
                if a!=b:
                    if parent[a]>parent[b]:
                        a,b=b,a
                    parent[a]+=parent[b]
                    parent[b]=a
            for i in groups.get(step,()):
                a,b=pairs[i]
                if root(a)==root(b):
                    high[i]=step
                else:
                    low[i]=step
    return [-1 if h>m else h for h in high]

def sol(lower, upper, divisor):
    from functools import lru_cache
    def count(value):
        if value<=0:
            return 0
        digits=[int(c) for c in str(value)]
        @lru_cache(None)
        def visit(i,prev,remainder,tight):
            if i==len(digits):
                return int(prev!=10 and remainder==0)
            stop=digits[i] if tight else 9
            answer=0
            for d in range(stop+1):
                if d==prev:
                    continue
                nxt=10 if prev==10 and d==0 else d
                answer+=visit(i+1,nxt,(remainder+d)%divisor,tight and d==stop)
            return answer
        return visit(0,10,0,True)
    return str(count(int(upper))-count(int(lower)-1))

def sol(values, penalty):
    from collections import deque
    # j번째 후보 직선의 기울기는 -2 prefix[j], 절편은 dp[j]+prefix[j]^2입니다.
    hull=deque([(0,0)])
    x=cost=0
    def at(line,x):
        return line[0]*x+line[1]
    for value in values:
        x+=value
        while len(hull)>1 and at(hull[1],x)<=at(hull[0],x):
            hull.popleft()
        cost=x*x+penalty+at(hull[0],x)
        m,b=-2*x,cost+x*x
        while len(hull)>1:
            p,q=hull[-2],hull[-1]
            if (q[1]-p[1])*(q[0]-m)<(b-q[1])*(p[0]-q[0]):
                break
            hull.pop()
        hull.append((m,b))
    return str(cost)

def sol(values, groups):
    n=len(values)
    prefix=[0]
    for x in values:
        prefix.append(prefix[-1]+x)
    inf=2**62
    prev=[0]+[inf]*n
    for g in range(1,groups+1):
        cur=[inf]*(n+1)
        def fill(l,r,lo,hi):
            if l>r:
                return
            mid=(l+r)//2
            best=lo
            for j in range(lo,min(hi,mid-1)+1):
                price=prev[j]+(prefix[mid]-prefix[j])**2
                if price<cur[mid]:
                    cur[mid]=price
                    best=j
            fill(l,mid-1,lo,best)
            fill(mid+1,r,best,hi)
        fill(g,n,g-1,n-1)
        prev=cur
    return str(prev[n])

def sol(weights):
    n=len(weights)
    sums=[0]
    for v in weights:
        sums.append(sums[-1]+v)
    dp=[[0]*n for _ in range(n)]
    opt=[[i]*n for i in range(n)]
    for length in range(2,n+1):
        for l in range(n-length+1):
            r=l+length-1
            cost=2**62
            for k in range(opt[l][r-1],min(r-1,opt[l+1][r])+1):
                price=dp[l][k]+dp[k+1][r]
                if price<cost:
                    cost=price
                    opt[l][r]=k
            dp[l][r]=cost+sums[r+1]-sums[l]
    return str(dp[0][-1])

def sol(limit, divisors):
    from math import gcd
    unique=[]
    for d in sorted(set(divisors)):
        if d<=limit and all(d%x for x in unique):
            unique.append(d)
    def count(start,period):
        result=0
        for j in range(start,len(unique)):
            d=unique[j]
            # 먼저 나누어 불필요하게 큰 최소공배수의 곱을 피합니다.
            factor=d//gcd(period,d)
            if period<=limit//factor:
                new=period*factor
                result+=limit//new-count(j+1,new)
        return result
    return count(0,1)

def sol(first, second):
    prime=998244353
    if not first or not second:
        return []
    size=1
    while size<len(first)+len(second)-1:
        size*=2
    def transform(a,inverse):
        j=0
        for i in range(1,size):
            bit=size//2
            while j&bit:
                j^=bit
                bit//=2
            j^=bit
            if i<j:
                a[i],a[j]=a[j],a[i]
        width=2
        while width<=size:
            root=pow(3,(prime-1)//width,prime)
            if inverse:
                root=pow(root,prime-2,prime)
            half=width//2
            for start in range(0,size,width):
                w=1
                for i in range(start,start+half):
                    u,v=a[i],a[i+half]*w%prime
                    a[i]=(u+v)%prime
                    a[i+half]=(u-v)%prime
                    w=w*root%prime
            width*=2
        if inverse:
            normalizer=pow(size,prime-2,prime)
            for i in range(size):
                a[i]=a[i]*normalizer%prime
    a=first+[0]*(size-len(first))
    b=second+[0]*(size-len(second))
    transform(a,False)
    transform(b,False)
    c=[x*y%prime for x,y in zip(a,b)]
    transform(c,True)
    return c[:len(first)+len(second)-1]
